import React, { useState, useEffect, useRef } from 'react';
import { Flow } from 'flow-sdk';
import { 
  SectionLabel, 
  PillButton, 
  FieldDropdown, 
  DragNumberField, 
  TextInput,
  RangeSlider,
  SegmentedToggle
} from './components/Controls';
import { PreviewArea } from './components/PreviewArea';
import { LoadingOverlay } from './components/LoadingOverlay';

const EMOTIONS = [
  'Happy', 'Sad', 'Angry', 'Surprised', 'Fearful', 
  'Disgusted', 'Neutral', 'Winking', 'Laughing', 'Crying',
  'Thinking', 'Screaming', 'Smiling', 'Smirking'
];

const MODELS = [
  '🍌 Nano Banana Pro',
  '🍌 Nano Banana 2',
  'Imagen 4 (Leaving 6/16)'
];

export default function App() {
  const [sourceImage, setSourceImage] = useState<any>(null);
  const [resultImage, setResultImage] = useState<any>(null);
  const [emotion, setEmotion] = useState('Happy');
  const [intensity, setIntensity] = useState(80);
  const [customPrompt, setCustomPrompt] = useState('');
  const [useEpicPrompt, setUseEpicPrompt] = useState('Off');
  const [model, setModel] = useState('🍌 Nano Banana Pro');
  const [isGenerating, setIsGenerating] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [saveState, setSaveState] = useState<'idle' | 'saving' | 'saved' | 'error'>('idle');

  // Inject global styles including slider track/thumb
  useEffect(() => {
    const id = 'flow-face-morph-css';
    if (document.getElementById(id)) return;
    const style = document.createElement('style');
    style.id = id;
    style.textContent = `
      html, body, #root { margin: 0; padding: 0; width: 100%; height: 100%; background: #0e0e0e; color: white; overflow: hidden; }
      .dark-scrollbar::-webkit-scrollbar { width: 4px; }
      .dark-scrollbar::-webkit-scrollbar-track { background: transparent; }
      .dark-scrollbar::-webkit-scrollbar-thumb { background: #333; border-radius: 10px; }
      @keyframes fade-in { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
      .animate-fade-in { animation: fade-in 0.3s ease-out forwards; }

      input[type=range] { -webkit-appearance: none; appearance: none; background: transparent; width: 100%; cursor: pointer; padding: 8px 0; }
      input[type=range]::-webkit-slider-runnable-track { width: 100%; height: 3px; background: #595959; border-radius: 9999px; }
      input[type=range]::-webkit-slider-thumb { -webkit-appearance: none; appearance: none; width: 14px; height: 14px; border-radius: 50%; background: white; box-shadow: 0px 1px 3px rgba(0,0,0,0.5); margin-top: -5.5px; cursor: grab; }
      input[type=range]::-webkit-slider-thumb:active { cursor: grabbing; }
      input[type=range]::-moz-range-track { width: 100%; height: 3px; background: #595959; border-radius: 9999px; }
      input[type=range]::-moz-range-thumb { width: 14px; height: 14px; border: none; border-radius: 50%; background: white; box-shadow: 0px 1px 3px rgba(0,0,0,0.5); cursor: grab; }
    `;
    document.head.appendChild(style);
  }, []);

  const handleSelectImage = async () => {
    try {
      const media = await Flow.media.select({ filter: 'image' });
      if (media) {
        setSourceImage(media);
        setResultImage(null);
        setError(null);
      }
    } catch (err) {
      console.error(err);
    }
  };

  const handleGenerate = async () => {
    if (!sourceImage) {
      setError('Please select a source image first.');
      return;
    }

    setIsGenerating(true);
    setError(null);

    try {
      const intensityScale = intensity / 100;
      let prompt = "";

      if (useEpicPrompt === 'On' && customPrompt.trim()) {
        // Epic Combination Mode
        prompt = `Highly detailed portrait. The person has a ${emotion.toLowerCase()} facial expression modified by: ${customPrompt.trim()}. Intensity of emotion: ${intensity}%. Maintain exact person identity, clothing, lighting, and cinematic background. Ultra-realistic, 8k.`;
      } else {
        // Standard Mode
        const intensityText = intensity > 85 ? 'extremely ' : intensity < 35 ? 'slightly ' : '';
        prompt = `A detailed realistic portrait showing a ${intensityText}${emotion.toLowerCase()} facial expression. High fidelity, maintaining the exact identity and background of the reference image. Perfect facial anatomy.`;
      }

      const result = await Flow.generate.image({
        prompt,
        modelDisplayName: model,
        referenceImageMediaIds: [sourceImage.mediaId],
        aspectRatio: '1:1', 
      });

      setResultImage(result);
    } catch (err: any) {
      setError(err.message || 'Generation failed. Please try again.');
    } finally {
      setIsGenerating(false);
    }
  };

  const handleSave = async () => {
    if (!resultImage) return;
    setSaveState('saving');
    try {
      await Flow.save({
        base64: resultImage.base64,
        mimeType: resultImage.mimeType as any,
        name: `Face Morph - ${emotion}`
      });
      setSaveState('saved');
      setTimeout(() => setSaveState('idle'), 2000);
    } catch (err) {
      setSaveState('error');
      setTimeout(() => setSaveState('idle'), 3000);
    }
  };

  const handleDownload = async () => {
    if (!resultImage) return;
    try {
      await Flow.download({
        base64: resultImage.base64,
        mimeType: resultImage.mimeType,
        filename: `face_morph_${emotion.toLowerCase()}.png`
      });
    } catch (err) {
      console.error(err);
    }
  };

  const saveLabel = {
    idle: 'Save to Gallery',
    saving: 'Saving...',
    saved: 'Saved ✓',
    error: 'Save Failed',
  }[saveState];

  return (
    <div className="flex h-screen w-screen bg-[#0e0e0e]">
      {/* Left Panel */}
      <div className="relative border-r border-[rgba(218,220,224,0.15)] flex flex-col items-start justify-between overflow-clip px-[10px] py-[12px] w-[300px] h-full min-h-0 bg-[#0e0e0e] z-10">
        <div className="flex flex-col gap-[24px] items-start w-full overflow-y-auto dark-scrollbar pr-1">

          {/* Input Section */}
          <div className="flex flex-col gap-2 items-start w-full">
            <SectionLabel>Source Image</SectionLabel>
            {sourceImage ? (
              <div className="relative w-full aspect-square rounded-xl overflow-hidden border border-[#595959] group">
                <img 
                  src={`data:${sourceImage.mimeType};base64,${sourceImage.base64}`} 
                  className="w-full h-full object-cover" 
                  alt="Source"
                />
                <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                  <PillButton 
                    variant="outline" 
                    onClick={handleSelectImage}
                    icon={<span className="material-symbols-outlined text-[18px]">cached</span>}
                  >
                    Change
                  </PillButton>
                </div>
              </div>
            ) : (
              <PillButton 
                variant="filled" 
                onClick={handleSelectImage}
                icon={<span className="material-symbols-outlined text-[18px]">add_photo_alternate</span>}
              >
                Select Image
              </PillButton>
            )}
          </div>

          {/* Expression Controls */}
          <div className="flex flex-col gap-2 items-start w-full">
            <SectionLabel>Expression</SectionLabel>
            <div className="flex flex-col gap-1.5 items-start w-full">
              <FieldDropdown 
                label="Emotion" 
                value={emotion} 
                options={EMOTIONS} 
                onChange={setEmotion} 
                className="w-full"
              />
              <div className="flex gap-1 w-full items-end">
                <div className="flex-1">
                  <RangeSlider 
                    label="Intensity" 
                    value={intensity} 
                    min={0} 
                    max={100} 
                    formatValue={(v) => `${v}%`} 
                    onChange={setIntensity} 
                  />
                </div>
                <DragNumberField 
                  label="Value" 
                  value={intensity} 
                  min={0} 
                  max={100} 
                  suffix="%" 
                  onChange={setIntensity} 
                  className="w-[70px]"
                />
              </div>
            </div>
          </div>

          {/* Settings */}
          <div className="flex flex-col gap-2 items-start w-full">
            <SectionLabel>Customization</SectionLabel>
            <div className="flex flex-col gap-1.5 items-start w-full">
              <div className="flex items-center justify-between w-full px-2 mb-1">
                <span className="text-[11px] font-medium text-white/40">Combine Custom Prompt</span>
                <div className="w-[80px]">
                  <SegmentedToggle 
                    value={useEpicPrompt} 
                    onChange={setUseEpicPrompt}
                    items={[{ value: 'Off', label: 'Off' }, { value: 'On', label: 'On' }]}
                  />
                </div>
              </div>
              <TextInput 
                value={customPrompt} 
                onChange={setCustomPrompt} 
                placeholder="e.g. adding a mischievous glint in the eyes..."
              />
              <p className="px-2 text-[10px] text-white/30 italic">
                {useEpicPrompt === 'On' 
                  ? "Combine mode: Custom details will be mixed with your emotion & intensity." 
                  : "Standard mode: Prompt replaces default emotion logic."}
              </p>
            </div>
          </div>

          <div className="flex flex-col gap-2 items-start w-full">
            <SectionLabel>Model</SectionLabel>
            <FieldDropdown 
              label="AI Model" 
              value={model} 
              options={MODELS} 
              onChange={setModel} 
              className="w-full"
            />
          </div>

          {error && (
            <div className="p-3 rounded-xl bg-red-500/10 border border-red-500/20 text-red-400 text-[11px] font-medium w-full animate-fade-in">
              {error}
            </div>
          )}
        </div>

        {/* Action Buttons */}
        <div className="flex flex-col gap-[5px] items-start w-full pt-4 border-t border-[rgba(218,220,224,0.1)] mt-4">
          <PillButton 
            variant="solid" 
            onClick={handleGenerate}
            disabled={isGenerating || !sourceImage}
            icon={isGenerating ? <div className="w-4 h-4 border-2 border-black/20 border-t-black rounded-full animate-spin" /> : <span className="material-symbols-outlined text-[18px]">auto_fix_high</span>}
          >
            {isGenerating ? 'Morphing...' : 'Generate Expression'}
          </PillButton>
        </div>
      </div>

      {/* Main Content Area */}
      <div className="flex-1 relative flex items-center justify-center p-8 bg-[#0e0e0e]">
        <PreviewArea 
          source={sourceImage} 
          result={resultImage} 
          isGenerating={isGenerating}
        />

        {resultImage && !isGenerating && (
          <div className="absolute bottom-8 right-8 flex gap-2 animate-fade-in">
             <PillButton 
              variant="outline" 
              onClick={handleDownload}
              icon={<span className="material-symbols-outlined text-[18px]">download</span>}
            >
              Download
            </PillButton>
            <PillButton 
              variant="solid" 
              onClick={handleSave}
              disabled={saveState !== 'idle'}
              icon={<span className="material-symbols-outlined text-[18px]">{saveState === 'saved' ? 'check' : 'save'}</span>}
            >
              {saveLabel}
            </PillButton>
          </div>
        )}
      </div>

      {isGenerating && <LoadingOverlay emotion={emotion} />}
    </div>
  );
}

import React, { useState, useEffect, useRef } from 'react';

export const SectionLabel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <div className="flex items-center px-2">
    <span className="text-[11px] font-medium text-[rgba(218,220,224,0.9)] tracking-[0.1px] normal-case">
      {children}
    </span>
  </div>
);

export const PillButton: React.FC<{
  icon?: React.ReactNode; 
  children: React.ReactNode;
  variant?: 'filled' | 'outline' | 'solid'; 
  onClick?: () => void;
  disabled?: boolean;
}> = ({ icon, children, variant = 'filled', onClick, disabled }) => {
  const base = 'flex items-center gap-[2px] justify-center w-full h-[34px] rounded-xl font-medium tracking-[0.1px] transition-all cursor-pointer disabled:opacity-50 disabled:cursor-not-allowed';
  const variants: Record<string, string> = {
    filled: 'bg-[#969696] hover:bg-[#a6a6a6] active:bg-[#868686] text-black text-[11px] pl-[8px] pr-[24px] py-1 select-none',
    outline: 'border border-[#595959] hover:bg-white/5 active:bg-white/10 backdrop-blur-[40px] text-[12px] pl-[8px] pr-[16px] py-2 text-white select-none',
    solid: 'bg-white hover:bg-gray-200 active:bg-gray-300 text-black text-[12px] pl-[8px] pr-[16px] py-2 select-none',
  };
  return (
    <button className={`${base} ${variants[variant]}`} onClick={onClick} disabled={disabled}>
      {icon && <span className="flex items-center justify-center w-6 h-6">{icon}</span>}
      <span>{children}</span>
    </button>
  );
};

function useOnClickOutside(ref: React.RefObject<HTMLElement | null>, handler: (e: MouseEvent | TouchEvent) => void) {
  useEffect(() => {
    const listener = (event: MouseEvent | TouchEvent) => {
      if (!ref.current || ref.current.contains(event.target as Node)) return;
      handler(event);
    };
    document.addEventListener('mousedown', listener);
    document.addEventListener('touchstart', listener);
    return () => { 
      document.removeEventListener('mousedown', listener); 
      document.removeEventListener('touchstart', listener); 
    };
  }, [ref, handler]);
}

export const FieldDropdown: React.FC<{
  label: string; 
  value: string; 
  options: string[];
  onChange: (val: string) => void; 
  className?: string;
}> = ({ label, value, options, onChange, className = '' }) => {
  const [isOpen, setIsOpen] = useState(false);
  const ref = useRef<HTMLDivElement>(null);
  useOnClickOutside(ref, () => setIsOpen(false));

  return (
    <div ref={ref} className={`relative ${className}`}>
      <button type="button" onClick={() => setIsOpen(!isOpen)}
        className="w-full text-left border border-[#595959] hover:border-[#7a7a7a] transition-colors rounded-xl flex flex-col gap-0.5 justify-center pb-2 pl-2.5 pr-1 pt-[5px] select-none focus:outline-none">
        <p className="text-[11px] font-medium text-[rgba(255,255,255,0.35)] tracking-[0.1px]">{label}</p>
        <div className="flex items-center justify-between">
          <span className="text-[11px] font-medium text-white tracking-[0.1px]">{value}</span>
          <span className={`material-symbols-outlined text-[16px] text-[rgba(218,220,224,0.5)] mr-1 transition-transform ${isOpen ? 'rotate-180' : ''}`}>keyboard_arrow_down</span>
        </div>
      </button>
      {isOpen && (
        <div className="absolute z-50 top-[calc(100%+4px)] left-0 w-full bg-[#0e0e0e] border border-[#595959] rounded-xl overflow-hidden shadow-2xl backdrop-blur-md animate-fade-in origin-top max-h-60 overflow-y-auto dark-scrollbar">
          {options.map((opt) => (
            <button key={opt} type="button"
              className={`w-full text-left px-2.5 py-2 text-[11px] font-medium tracking-[0.1px] hover:bg-[#1a1a1a] transition-colors ${value === opt ? 'bg-[#1a1a1a] text-white' : 'text-[rgba(218,220,224,0.9)]'}`}
              onClick={() => { onChange(opt); setIsOpen(false); }}>
              {opt}
            </button>
          ))}
        </div>
      )}
    </div>
  );
};

export const DragNumberField: React.FC<{
  label: string; 
  value: number; 
  min?: number; 
  max?: number;
  step?: number; 
  suffix?: string; 
  onChange: (val: number) => void; 
  className?: string;
}> = ({ label, value, min = 0, max = 999, step = 1, suffix = 'px', onChange, className = '' }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [editValue, setEditValue] = useState(String(value));
  const inputRef = useRef<HTMLInputElement>(null);
  const dragRef = useRef<{ startY: number; startVal: number; moved: boolean } | null>(null);

  const commitEdit = (raw: string) => {
    const parsed = parseFloat(raw);
    if (!isNaN(parsed)) onChange(Math.min(max, Math.max(min, Math.round(parsed / step) * step)));
    setIsEditing(false);
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    if (isEditing) return;
    e.preventDefault();
    dragRef.current = { startY: e.clientY, startVal: value, moved: false };
    const handleMouseMove = (ev: MouseEvent) => {
      if (!dragRef.current) return;
      if (Math.abs(ev.clientY - dragRef.current.startY) > 3) dragRef.current.moved = true;
      if (dragRef.current.moved) {
        const delta = dragRef.current.startY - ev.clientY;
        const newVal = Math.round((dragRef.current.startVal + delta * step) / step) * step;
        onChange(Math.min(max, Math.max(min, newVal)));
        document.body.style.cursor = 'ns-resize';
      }
    };
    const handleMouseUp = () => {
      const wasDrag = dragRef.current?.moved;
      dragRef.current = null;
      document.removeEventListener('mousemove', handleMouseMove);
      document.removeEventListener('mouseup', handleMouseUp);
      document.body.style.cursor = '';
      if (!wasDrag) {
        setEditValue(String(value));
        setIsEditing(true);
        setTimeout(() => inputRef.current?.select(), 0);
      }
    };
    document.addEventListener('mousemove', handleMouseMove);
    document.addEventListener('mouseup', handleMouseUp);
  };

  return (
    <div className={`border border-[#595959] hover:border-[#7a7a7a] rounded-xl flex flex-col gap-0.5 justify-center pb-2 pl-2.5 pr-1 pt-[5px] select-none transition-colors ${isEditing ? '' : 'cursor-ns-resize'} ${className}`}
      onMouseDown={handleMouseDown}>
      <p className="text-[11px] font-medium text-[rgba(255,255,255,0.35)] tracking-[0.1px]">{label}</p>
      <div className="flex items-center justify-between">
        {isEditing ? (
          <input ref={inputRef} type="text" value={editValue}
            onChange={(e) => setEditValue(e.target.value)}
            onKeyDown={(e) => { if (e.key === 'Enter') commitEdit(editValue); if (e.key === 'Escape') setIsEditing(false); }}
            onBlur={() => commitEdit(editValue)}
            className="bg-transparent text-[11px] font-medium text-white tracking-[0.1px] outline-none w-full border-none p-0 m-0" autoFocus />
        ) : (
          <>
            <span className="text-[11px] font-medium text-white tracking-[0.1px] cursor-text">{value}{suffix}</span>
            <div className="flex flex-col items-center mr-1.5 -gap-px text-white/40">
              <svg width="10" height="6" viewBox="0 0 10 6" fill="none"><path d="M5 0L9 5H1L5 0Z" fill="currentColor"/></svg>
              <svg width="10" height="6" viewBox="0 0 10 6" fill="none"><path d="M5 6L1 1H9L5 6Z" fill="currentColor"/></svg>
            </div>
          </>
        )}
      </div>
    </div>
  );
};

export const RangeSlider: React.FC<{
  label: string; 
  value: number; 
  min: number; 
  max: number;
  step?: number; 
  formatValue?: (val: number) => string;
  onChange: (val: number) => void;
}> = ({ label, value, min, max, step = 1, formatValue = (v) => String(v), onChange }) => (
  <div className="flex flex-col gap-2 pt-2 pb-[5px] w-full">
    <div className="flex items-center justify-between px-2 select-none">
      <span className="text-[11px] font-medium text-[rgba(218,220,224,0.9)] tracking-[0.1px]">{label}</span>
      <span className="text-[11px] font-medium text-[#c7c9cd] tracking-[0.1px]">{formatValue(value)}</span>
    </div>
    <div className="px-2 w-full flex items-center h-2">
      <input type="range" min={min} max={max} step={step} value={value}
        onChange={(e) => onChange(Number(e.target.value))} />
    </div>
  </div>
);

export const SegmentedToggle: React.FC<{
  value: string; 
  items: { value: string; label: string; icon?: React.ReactNode }[];
  onChange: (val: string) => void;
}> = ({ value, items, onChange }) => (
  <div className="flex w-full items-center border border-[#595959] rounded-xl overflow-hidden bg-transparent">
    {items.map((item) => (
      <button key={item.value} type="button" onClick={() => onChange(item.value)}
        className={`flex-1 flex items-center justify-center gap-1 h-[34px] px-3 py-2 rounded-xl text-[12px] font-medium tracking-[0.1px] transition-all cursor-pointer ${
          value === item.value ? 'bg-[#969696] text-black' : 'text-[rgba(218,220,224,0.75)] hover:text-white hover:bg-white/5'
        }`}>
        {item.icon}<span>{item.label}</span>
      </button>
    ))}
  </div>
);

export const TextInput: React.FC<{
  value: string; 
  onChange: (val: string) => void; 
  placeholder?: string;
}> = ({ value, onChange, placeholder }) => (
  <textarea 
    value={value} 
    onChange={(e) => onChange(e.target.value)} 
    placeholder={placeholder}
    className="border border-[#595959] hover:border-[#7a7a7a] focus:border-[#969696] rounded-xl w-full h-[60px] px-3 py-2.5 resize-none bg-transparent text-[11px] font-medium text-white placeholder-[rgba(218,220,224,0.4)] tracking-[0.1px] focus:outline-none transition-colors dark-scrollbar" 
  />
);

import React from 'react';

interface PreviewAreaProps {
  source: any;
  result: any;
  isGenerating: boolean;
}

export const PreviewArea: React.FC<PreviewAreaProps> = ({ source, result, isGenerating }) => {
  if (!source && !result && !isGenerating) {
    return (
      <div className="flex flex-col items-center justify-center text-center max-w-sm">
        <div className="w-20 h-20 rounded-full bg-white/5 flex items-center justify-center mb-6">
          <span className="material-symbols-outlined text-[40px] text-white/20">face</span>
        </div>
        <h2 className="text-xl font-medium text-white mb-2">Start Morphing</h2>
        <p className="text-white/40 text-sm leading-relaxed">
          Select a portrait image from your gallery to start changing expressions and emotions.
        </p>
      </div>
    );
  }

  return (
    <div className="relative w-full h-full flex items-center justify-center gap-8">
      {/* Source Preview */}
      {source && (
        <div className={`flex flex-col gap-3 transition-all duration-700 ${result ? 'w-1/3 opacity-40 scale-90' : 'w-full max-w-2xl'}`}>
          <div className="flex justify-between items-center px-2">
            <span className="text-[11px] font-medium text-white/50 uppercase tracking-widest">Original</span>
          </div>
          <div className="rounded-2xl overflow-hidden border border-white/10 shadow-2xl">
            <img 
              src={`data:${source.mimeType};base64,${source.base64}`} 
              className="w-full h-auto object-contain" 
              alt="Source"
            />
          </div>
        </div>
      )}

      {/* Generation Result */}
      {(result || isGenerating) && (
        <div className="flex flex-col gap-3 w-2/3 max-w-3xl animate-fade-in">
          <div className="flex justify-between items-center px-2">
            <span className="text-[11px] font-medium text-white/50 uppercase tracking-widest">Morphed</span>
            {isGenerating && (
              <span className="text-[11px] text-[#969696] animate-pulse">Processing pixels...</span>
            )}
          </div>
          <div className="relative rounded-2xl overflow-hidden border border-white/20 shadow-[0_0_50px_rgba(255,255,255,0.05)] bg-[#111]">
            {isGenerating ? (
              <div className="aspect-square w-full flex items-center justify-center">
                <div className="flex flex-col items-center gap-4">
                  <div className="w-12 h-12 border-4 border-white/5 border-t-white/40 rounded-full animate-spin" />
                  <span className="text-sm text-white/30 font-medium">Synthesizing expression...</span>
                </div>
              </div>
            ) : (
              <img 
                src={`data:${result.mimeType};base64,${result.base64}`} 
                className="w-full h-auto object-contain" 
                alt="Result"
              />
            )}
          </div>
        </div>
      )}
    </div>
  );
};
